// ================= =================
// 1. الإعدادات والبيانات الأساسية
// ================= =================

// رابط الـ Webhook الخاص بك في الديسكورد
const DISCORD_WEBHOOK_URL = "https://discord.com/api/webhooks/1542554021510774814/kURM7_KSoI1f6-7rEopGSwzjQ26KJY_-OW9DTkvAiofOUms2wrsWr-BO2d7slwCs52j5";

// بيانات حساب الإدارة الخاص بك
const ADMIN_EMAIL = "admin@lora.com";
const ADMIN_PASS = "admin123";

// متغيرات النظام والمستخدم الحالي
let currentUser = null;
let cart = [];
let selectedPaymentMethod = "كاش (نقداً عند الاستلام)";
let tempAddressData = {
    governorate: "حولي",
    area: "السالمالية",
    block: "1",
    street: "10",
    avenue: "1",
    house: "5"
};

// قائمة المنتجات الابتدائية
let productsList = [
    { id: 1, title: "Jura E8 Piano Black", price: 550.000, img: "https://via.placeholder.com/150" }
];

// قائمة أكواد الخصم
let promoCodes = [
    { code: "LORA10", discountPercent: 10 }
];

// ================= =================
// 2. نظام تسجيل الدخول والخروج والتحكم
// ================= =================

function loginUser() {
    const email = document.getElementById('loginEmail').value.trim();
    const pass = document.getElementById('loginPass').value.trim();

    if (!email || !pass) {
        showScreenBanner("warning", "يرجى كتابة البريد الإلكتروني وكلمة المرور!");
        return;
    }

    // التحقق هل الحساب أدمن أم عميل طبيعي
    if (email === ADMIN_EMAIL && pass === ADMIN_PASS) {
        currentUser = { email: email, phone: "97114109", isAdmin: true };
        document.getElementById('adminDashboardSection').style.display = 'block';
        showScreenBanner("success", "👑 تم تسجيل الدخول كـ أدمن! فتحت لوحة التحكم الإدارية.");
    } else {
        currentUser = { email: email, phone: "97114109", isAdmin: false };
        document.getElementById('adminDashboardSection').style.display = 'none';
        showScreenBanner("success", "👤 تم تسجيل الدخول كعميل بنجاح.");
    }

    document.getElementById('userStatusText').innerText = `مسجل كـ: ${currentUser.email}`;
    document.getElementById('loginSection').style.display = 'none';
    document.getElementById('storeSection').style.display = 'block';
}

function logoutUser() {
    currentUser = null;
    document.getElementById('adminDashboardSection').style.display = 'none';
    document.getElementById('storeSection').style.display = 'none';
    document.getElementById('loginSection').style.display = 'block';
    showScreenBanner("info", "👋 تم تسجيل الخروج وعودة المتجر للوضع الطبيعي.");
}

// ================= =================
// 3. نظام إرسال الطلب عبر Webhook الديسكورد
// ================= =================

function checkoutOrder() {
    if (!currentUser) {
        showScreenBanner("warning", "🔒 يرجى تسجيل الدخول أولاً!");
        return;
    }

    if (cart.length === 0) {
        showScreenBanner("warning", "🛒 السلة فارغة! أضف منتجات قبل الشراء.");
        return;
    }

    const currentOrderNum = Math.floor(Math.random() * 900) + 10;
    const orderID = `#ORD-2026-${currentOrderNum}`;

    const addressFormatted = `• المحافظة: ${tempAddressData.governorate}\n• المنطقة: ${tempAddressData.area}\n• القطعة: ${tempAddressData.block}\n• الشارع: ${tempAddressData.street}\n• الجادة: ${tempAddressData.avenue}\n• المنزل: ${tempAddressData.house}`;
    
    // تجميع المنتجات وإجمالي العدد والمبلغ
    let itemsList = cart.map(i => `• ${i.title} (${i.price.toFixed(3)} د.ك)`).join('\n');
    let totalItemsCount = cart.length;
    let totalSum = cart.reduce((a, b) => a + b.price, 0).toFixed(3);

    // تجهيز الـ Embed المنسق تماماً كما بالصورة
    const embedPayload = {
        embeds: [{
            title: `☕ طلب جديد في الانتظار - محمصة لورا (${orderID})`,
            description: "**الإجراء المطلوب:** يرجى مراجعة تفاصيل الطلب وتأكيده عبر لوحة التحكم.",
            color: 0x1F274A,
            fields: [
                { name: "💳 طريقة الدفع", value: selectedPaymentMethod, inline: true },
                { name: "💰 المجموع الكلي", value: `${totalSum} د.ك`, inline: true },
                { name: "🆔 رقم الطلب", value: orderID, inline: true },
                { name: "🛍️ مجموع المنتجات", value: `${totalItemsCount} منتج`, inline: true },
                { 
                    name: "👤 بيانات العميل", 
                    value: `• البريد: ${currentUser.email}\n• رقم الهاتف: ${currentUser.phone}`, 
                    inline: false 
                },
                { name: "📍 موقع البيت", value: addressFormatted, inline: false },
                { name: "🛒 المنتجات المطلوبة", value: itemsList, inline: false },
                { name: "⚡ التحكم الإداري بالطلب", value: "🔴 إلغاء ورفض الطلب | 🟢 تأكيد وقبول الطلب", inline: false }
            ],
            footer: { text: "نظام إشارات محمصة لورا عبر Webhook" },
            timestamp: new Date().toISOString()
        }]
    };

    // الإرسال المباشر لشبكة Discord
    fetch(DISCORD_WEBHOOK_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(embedPayload)
    }).then(() => {
        showScreenBanner("success", `🎉 تم إرسال طلبك ${orderID} بنجاح إلى الديسكورد!`);
        cart = [];
        updateCartUI();
    }).catch(err => {
        console.error(err);
        showScreenBanner("warning", "❌ حدث خطأ أثناء إرسال الطلب للديسكورد.");
    });
}

// ================= =================
// 4. وظائف لوحة التحكم الإدارية (Admin Only)
// ================= =================

function addProductByAdmin() {
    const title = document.getElementById('adminProdName').value;
    const price = document.getElementById('adminProdPrice').value;
    const img = document.getElementById('adminProdImg').value || "https://via.placeholder.com/150";

    if (!title || !price) {
        showScreenBanner("warning", "يرجى كتابة الاسم والسعر!");
        return;
    }

    productsList.push({ id: Date.now(), title, price: parseFloat(price), img });
    renderProducts();
    showScreenBanner("success", "✅ تم إضافة المنتج بنجاح للمتجر!");
}

function addPromoCodeByAdmin() {
    const code = document.getElementById('adminCode').value.toUpperCase();
    const discount = document.getElementById('adminDiscount').value;

    if (!code || !discount) {
        showScreenBanner("warning", "يرجى كتابة رمز الكود والنسبة!");
        return;
    }

    promoCodes.push({ code, discountPercent: parseFloat(discount) });
    showScreenBanner("success", `✅ تم إضافة كود الخصم (${code}) بنجاح!`);
}

// ================= =================
// 5. إدارة السلة وواجهة المتجر
// ================= =================

function renderProducts() {
    const container = document.getElementById('productsGrid');
    container.innerHTML = '';

    productsList.forEach(p => {
        container.innerHTML += `
            <div style="border: 1px solid #333; padding: 15px; border-radius: 8px; text-align: center; background: #252a3e;">
                <img src="${p.img}" style="width: 100%; max-height: 120px; object-fit: contain;">
                <h4>${p.title}</h4>
                <p style="color: #4caf50; font-weight: bold;">${p.price.toFixed(3)} د.ك</p>
                <button onclick="addToCart(${p.id})" style="background: #1f274a; color: white; border: none; padding: 8px 15px; border-radius: 5px; cursor: pointer;">إضافة للسلة 🛒</button>
            </div>
        `;
    });
}

function addToCart(id) {
    const item = productsList.find(p => p.id === id);
    if (item) {
        cart.push(item);
        updateCartUI();
        showScreenBanner("info", `تم إضافة ${item.title} للسلة`);
    }
}

function updateCartUI() {
    document.getElementById('cartCount').innerText = cart.length;
}

function showScreenBanner(type, message) {
    alert(`[${type.toUpperCase()}]: ${message}`);
}

// تشغيل الواجهة المبدئية عند التحميل
window.onload = () => {
    renderProducts();
};